CREATE OR REPLACE FUNCTION public.dp_plan_activate(pid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if auth.uid() is null or not dp_private.manage_voice() then raise exception 'Not authorized'; end if;
 update dp_voice_plans set status='active',approved_at=now() where id=pid and status='draft' and not is_sample;
 if not found then raise exception 'Only a student''s draft plan can be approved'; end if;
end $function$;
revoke all on function public.dp_plan_activate(pid uuid) from public, anon, authenticated, service_role;
grant execute on function public.dp_plan_activate(pid uuid) to postgres;
grant execute on function public.dp_plan_activate(pid uuid) to authenticated;
CREATE OR REPLACE FUNCTION public.dp_plan_copy_sample(sample uuid, student uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p dp_voice_plans; us jsonb;
begin
 if auth.uid() is null or not dp_private.manage_voice() then raise exception 'Not authorized'; end if;
 select * into p from dp_voice_plans where id=sample and is_sample;
 if not found then raise exception 'Sample not found'; end if;
 select jsonb_agg(to_jsonb(u)-'id'-'plan_id'-'status'-'assigned_assignment_id' order by seq) into us from dp_voice_plan_units u where plan_id=sample;
 return public.dp_plan_save(null,student,p.title||' (draft for review)',p.package_type,us,p.basis,array_append(p.notes,'Copied from a sample pathway. Review every lesson before approving.'),'{}','Started from a sample, not from this student''s findings. Replace with observed findings.');
end $function$;
revoke all on function public.dp_plan_copy_sample(sample uuid, student uuid) from public, anon, authenticated, service_role;
grant execute on function public.dp_plan_copy_sample(sample uuid, student uuid) to postgres;
grant execute on function public.dp_plan_copy_sample(sample uuid, student uuid) to authenticated;
CREATE OR REPLACE FUNCTION public.dp_progress_check_save(pid uuid, wk integer, check_kind text, rate jsonb, good text, focus text, private_notes text, share boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cid uuid:=gen_random_uuid(); sid uuid;
begin
 if auth.uid() is null or not dp_private.manage_voice() then raise exception 'Not authorized'; end if;
 select student_id into sid from dp_voice_plans where id=pid and not is_sample and status in ('active','completed');
 if sid is null then raise exception 'Progress checks belong to an approved student plan'; end if;
 insert into dp_voice_progress_checks(id,plan_id,student_id,week,kind,ratings,strengths,next_focus,shared_at,created_by)
 values(cid,pid,sid,wk,check_kind,coalesce(rate,'{}'),good,focus,case when share then now() end,auth.uid());
 insert into dp_voice_progress_check_private(check_id,notes) values(cid,private_notes);
 return cid;
end $function$;
revoke all on function public.dp_progress_check_save(pid uuid, wk integer, check_kind text, rate jsonb, good text, focus text, private_notes text, share boolean) from public, anon, authenticated, service_role;
grant execute on function public.dp_progress_check_save(pid uuid, wk integer, check_kind text, rate jsonb, good text, focus text, private_notes text, share boolean) to postgres;
grant execute on function public.dp_progress_check_save(pid uuid, wk integer, check_kind text, rate jsonb, good text, focus text, private_notes text, share boolean) to authenticated;
CREATE OR REPLACE FUNCTION public.dp_voice_import_intake(student uuid, a jsonb, requested_tracks text[] DEFAULT '{}'::text[], submitted timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare iid uuid:=gen_random_uuid(); t text[]:=coalesce(requested_tracks,'{}');
begin
 if auth.uid() is null or not dp_private.manage_voice() then raise exception 'Not authorized'; end if;
 if not dp_private.voice_member(student) then raise exception 'That person is not enrolled in Voice'; end if;
 if not (t <@ array['worship_leadership','spontaneous_expression','prophetic_worship']) then raise exception 'Unknown track'; end if;
 insert into dp_voice_intakes(id,student_id,source,answers,submitted_at,imported_by) values(iid,student,'google_forms_import',a,coalesce(submitted,now()),auth.uid());
 insert into dp_voice_profiles(student_id,selected_tracks) values(student,t)
 on conflict(student_id) do update set selected_tracks=excluded.selected_tracks,
  approved_tracks=array(select x from unnest(dp_voice_profiles.approved_tracks) x where x=any(excluded.selected_tracks)),
  tongues_requested=dp_voice_profiles.tongues_requested and 'prophetic_worship'=any(excluded.selected_tracks),updated_at=now();
 return iid;
end $function$;
revoke all on function public.dp_voice_import_intake(student uuid, a jsonb, requested_tracks text[], submitted timestamp with time zone) from public, anon, authenticated, service_role;
grant execute on function public.dp_voice_import_intake(student uuid, a jsonb, requested_tracks text[], submitted timestamp with time zone) to postgres;
grant execute on function public.dp_voice_import_intake(student uuid, a jsonb, requested_tracks text[], submitted timestamp with time zone) to authenticated;
commit;
